<?php
if(session_status()===PHP_SESSION_NONE)session_start();
if(empty($_SESSION['hotel_staff'])){header('Location: /travelix/hotel_portal/login.php');exit;}
$baseUrl='/travelix'; require_once $_SERVER['DOCUMENT_ROOT'].$baseUrl.'/config/firebase_config.php'; require_once $_SERVER['DOCUMENT_ROOT'].$baseUrl.'/includes/firestore_admin.php'; require_once __DIR__.'/includes/resolve_hotel.php';
$sa=$_SERVER['DOCUMENT_ROOT'].$baseUrl.'/config/firebase-service-account.json'; $hotel=hp_get_staff_hotel($sa,FIREBASE_PROJECT_ID,(string)($_SESSION['hotel_staff']['uid']??'')); $hotelId=(string)($hotel['id']??'');
$rows=$hotelId?hp_firestore_query($sa,FIREBASE_PROJECT_ID,'notifications','hotelId',$hotelId):[]; $rows=array_values(array_filter($rows,fn($n)=>(string)($n['audience']??'')==='hotel')); usort($rows,fn($a,$b)=>strtotime((string)($b['createdAt']??''))<=>strtotime((string)($a['createdAt']??''))); function hh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications — Hotel Portal</title><link rel="stylesheet" href="/travelix/assets/vendor/fontawesome/all.min.css"><style>body{margin:0;background:#f1f5f9;font-family:Segoe UI,sans-serif;color:#0f172a}.top{background:linear-gradient(135deg,#0f3460,#1484B4);color:#fff;padding:18px 5%;display:flex;justify-content:space-between;align-items:center}.top a{color:#fff;text-decoration:none;font-weight:700}.wrap{max-width:980px;margin:28px auto;padding:0 16px}.card{background:#fff;border-radius:20px;box-shadow:0 3px 18px #0f172a12;overflow:hidden}.head{padding:22px 25px;border-bottom:1px solid #e5e7eb}.notice{display:flex;gap:14px;padding:18px 24px;border-bottom:1px solid #eef2f7;color:#0f172a;text-decoration:none}.notice:hover{background:#f8fbff}.notice.unread{border-left:4px solid #1484B4;background:#f0f9ff}.notice h3{font-size:15px;margin:0 0 4px}.notice p{font-size:13px;color:#64748b;margin:0}.notice time{font-size:11px;color:#94a3b8}.empty{padding:50px;text-align:center;color:#94a3b8}</style></head><body><header class="top"><strong><i class="fas fa-bell"></i> Hotel Notifications</strong><a href="/travelix/hotel_portal/index.php">← Dashboard</a></header><main class="wrap"><div class="card"><div class="head"><h1 style="font-size:24px;margin:0">All Notifications</h1><p style="color:#64748b;margin:5px 0 0"><?= hh($hotel['name']??'Your hotel') ?> booking, payout and refund alerts.</p></div><?php if(!$rows):?><div class="empty">No notifications yet.</div><?php else:foreach($rows as $n):?><a class="notice <?= empty($n['isRead'])?'unread':'' ?>" href="<?= hh($n['link']??'#') ?>"><div><i class="<?= hh($n['icon']??'fa-solid fa-bell') ?>"></i></div><div><h3><?= hh($n['title']??'Notification') ?></h3><p><?= hh($n['message']??'') ?></p><time><?= hh($n['createdAt']??'') ?></time></div></a><?php endforeach;endif;?></div></main></body></html>
